async def preview_page(request: Request) -> HTMLResponse:
    """Mockup-first frontend preview.

    This route is intentionally isolated from canonical model/runtime logic. It exists
    so the full subscriber UX can be approved visually before wiring live payloads.
    """
    return HTMLResponse(_html())


